// Generated from src/registry/sources/control-ui/recipes/accordion.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const accordionKnobs = [
  "--cui-accordion-item-border-color",
  "--cui-accordion-trigger-foreground",
  "--cui-accordion-trigger-hover-foreground",
  "--cui-accordion-icon-foreground",
] as const;
export type AccordionKnobStyle = Partial<Record<(typeof accordionKnobs)[number], string>>;

@layer components {
  :where([data-control-family="accordion"][data-slot="root"]) {
    --cui-accordion-item-border-color: var(--border);
    --cui-accordion-trigger-foreground: var(--foreground);
    --cui-accordion-trigger-hover-foreground: oklch(from var(--foreground) l c h / 0.8);
    --cui-accordion-icon-foreground: var(--muted-foreground);
  }
  :where([data-control-family="accordion"][data-slot="item"]) {
    border-block-end: 1px solid var(--cui-accordion-item-border-color);
  }

  :where([data-control-family="accordion"][data-slot="item"]:last-child) {
    border-block-end: 0;
  }

  :where([data-control-family="accordion"][data-slot="trigger"]) {
    gap: calc(var(--spacing) * 4);
    padding-block: calc(var(--spacing) * 3);
    color: var(--cui-accordion-trigger-foreground);
    font-size: var(--text-body);
    outline: none;
    transition: color var(--duration-fast) var(--ease-standard);
    text-align: left;
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="accordion"][data-slot="trigger"]:hover) {
    color: var(--cui-accordion-trigger-hover-foreground);
  }

  :where([data-control-family="accordion"][data-slot="trigger"][data-disabled]) {
    cursor: not-allowed;
    opacity: 0.5;
  }

  :where([data-control-family="accordion"][data-slot="icon"]) {
    inline-size: calc(var(--spacing) * 4);
    block-size: calc(var(--spacing) * 4);
    color: var(--cui-accordion-icon-foreground);
    transition: rotate var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="accordion"][data-slot="trigger"][data-panel-open] > [data-slot="icon"]) {
    rotate: 180deg;
  }

  :where([data-control-family="accordion"][data-slot="panel-content"]) {
    padding-block-end: calc(var(--spacing) * 3);
  }

  :where([data-control-family="accordion"][data-slot="panel"]) {
    color: var(--muted-foreground);
    font-size: var(--text-body);
    height: var(--accordion-panel-height);
    overflow: hidden;
    transition: height var(--duration-base) var(--ease-emphasized);
  }

  :where([data-control-family="accordion"][data-slot="panel"][data-starting-style]),
  :where([data-control-family="accordion"][data-slot="panel"][data-ending-style]) {
    height: 0;
  }
}

@property --cui-accordion-item-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-accordion-trigger-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-accordion-trigger-hover-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-accordion-icon-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

"use client";

import { Accordion as AccordionPrimitive } from "@base-ui/react/accordion";
import { ChevronDown } from "lucide-react";
import type { ComponentProps, CSSProperties } from "react";
import type { AccordionKnobStyle } from "@/components/control-ui/knob-contracts/accordion-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export type AccordionValue = (string | number)[];

export type AccordionProps = Omit<ComponentProps<"div">, "defaultValue" | "onChange"> & {
  value?: AccordionValue;
  defaultValue?: AccordionValue;
  onValueChange?: (value: AccordionValue) => void;
  multiple?: boolean;
  disabled?: boolean;
} & { style?: CSSProperties & AccordionKnobStyle };

export type AccordionItemProps = Omit<
  ComponentProps<"div"> & {
    value?: string | number;
    disabled?: boolean;
  },
  "style"
> & { style?: CSSProperties & AccordionKnobStyle };

export type AccordionTriggerProps = Omit<ComponentProps<"button">, "style"> & { style?: CSSProperties & AccordionKnobStyle };

export type AccordionPanelProps = Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & AccordionKnobStyle };

// Panel height animates from Base UI's --accordion-panel-height, with no JS measuring.
export function Accordion({ className, ...props }: AccordionProps) {
  return (
    <AccordionPrimitive.Root
      data-control-ui="accordion"
      data-control-family="accordion"
      data-slot="root"
      className={className}
      {...props}
    />
  );
}

export function AccordionItem({ className, ...props }: AccordionItemProps) {
  return (
    <AccordionPrimitive.Item
      data-control-ui="accordion"
      data-control-family="accordion"
      data-slot="item"
      className={className}
      {...props}
    />
  );
}

export function AccordionTrigger({ className, children, ...props }: AccordionTriggerProps) {
  return (
    <AccordionPrimitive.Header className="flex">
      <AccordionPrimitive.Trigger
        data-control-ui="accordion"
        data-control-family="accordion"
        data-slot="trigger"
        className={cn("group flex flex-1 cursor-pointer select-none items-center justify-between", className)}
        {...props}
      >
        {children}
        <ChevronDown aria-hidden="true" data-control-ui="accordion" data-control-family="accordion" data-slot="icon" className="shrink-0" />
      </AccordionPrimitive.Trigger>
    </AccordionPrimitive.Header>
  );
}

export function AccordionPanel({ className, children, ...props }: AccordionPanelProps) {
  return (
    <AccordionPrimitive.Panel data-control-ui="accordion" data-control-family="accordion" data-slot="panel" {...props}>
      <div data-control-ui="accordion" data-control-family="accordion" data-slot="panel-content" className={className}>
        {children}
      </div>
    </AccordionPrimitive.Panel>
  );
}
